import{c as a,Q as s,j as t,m as n}from"./chunks/framework.DOi4mjdC.js";const l="/assets/%E5%90%8C%E6%AD%A5%E5%BC%82%E6%AD%A5%E5%9C%BA%E6%99%AF%E7%A4%BA%E6%84%8F%E5%9B%BE._S5Ec0NA.png",h=JSON.parse('{"title":"异步场景处理","description":"","frontmatter":{},"headers":[{"level":1,"title":"异步场景处理","slug":"异步场景处理"},{"level":2,"title":"功能介绍","slug":"功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/异步场景处理.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/异步场景处理.md"}'),p={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/异步场景处理.md"};function r(i,e,o,c,m,d){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="异步场景处理" tabindex="-1">异步场景处理 <a class="header-anchor" href="#异步场景处理" aria-label="Permalink to &quot;异步场景处理&quot;">​</a></h1><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><p>Matmul的<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Iterate.md" target="_blank" rel="noreferrer">Iterate</a>和<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/IterateAll.md" target="_blank" rel="noreferrer">IterateAll</a>接口在MIX场景（包含矩阵计算和矢量计算）下提供了同步和异步两种模式，纯Cube场景（只有矩阵计算）下，只支持同步模式。</p><p>同步模式指的是程序执行时，需要等待某个操作完成后才能继续执行下一步操作。 异步模式指的是程序执行时，不需要等待某个操作完成就可以继续执行下一步操作。</p><ul><li><p>Iterate&amp;GetTensorC的同步和异步</p><ul><li><p>同步：执行完一次Iterate迭代计算后，执行<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetTensorC.md" target="_blank" rel="noreferrer">GetTensorC</a>搬运矩阵C分片，搬运完成后，才能进行下一次计算。如下图所示，C矩阵中，矩阵块1搬走后，才能计算矩阵块2，矩阵块2搬运完成后，才能计算矩阵块3。</p><p><img src="'+l+`" alt=""></p><p>Iterate&amp;GetTensorC同步模式的关键代码示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>while (mm.Iterate()) {</span></span>
<span class="line"><span>    mm.GetTensorC(gm_c);</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>异步：通过设置Iterate接口的模板参数开启异步模式。调用Iterate后，无需立即调用GetTensorC同步等待矩阵C分块搬运完成，可以先执行其它操作，待需要获取结果时再调用GetTensorC。异步模式可以减少同步等待，提高并行度，开发者对计算性能要求较高时，可以选用该方式。异步场景时，需要使用一块临时空间来缓存Iterate计算结果，否则会覆盖计算结果，调用GetTensorC时会在该临时空间中获取C的矩阵分片。临时空间通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetWorkspace.md" target="_blank" rel="noreferrer">SetWorkspace</a>接口进行设置。SetWorkspace接口需要在Iterate接口之前调用。</p><p>Iterate&amp;GetTensorC异步模式的关键代码示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mm.SetWorkspace(workspace, size); // 其中，workspace为临时空间的物理地址，size为singleCoreM * singleCoreN的矩阵C大小</span></span>
<span class="line"><span>// 异步模式</span></span>
<span class="line"><span>mm.template Iterate&lt;false&gt;();</span></span>
<span class="line"><span>…… // 执行其他操作</span></span>
<span class="line"><span>auto mIter = Ceil(singleCoreM, baseM);</span></span>
<span class="line"><span>auto nIter = Ceil(singleCoreN, baseN);</span></span>
<span class="line"><span>for (int i = 0; i &lt; mIter * nIter ; ++i) {</span></span>
<span class="line"><span>    mm.GetTensorC&lt;false&gt; (gm_c);</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ul></li><li><p>IterateAll的同步和异步</p><ul><li><p>同步：后续操作需要同步等待IterateAll执行结束。</p><p>IterateAll同步模式的关键代码示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mm.SetTensorA(gm_a);    // 设置左矩阵A</span></span>
<span class="line"><span>mm.SetTensorB(gm_b);    // 设置右矩阵B</span></span>
<span class="line"><span>mm.SetBias(gm_bias);    // 设置Bias</span></span>
<span class="line"><span>mm.IterateAll(gm_c);</span></span>
<span class="line"><span>// 后续操作</span></span>
<span class="line"><span>...</span></span></code></pre></div></li><li><p>异步：后续操作不需要同步等待IterateAll执行结束，需要IterateAll的结果时，调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/WaitIterateAll.md" target="_blank" rel="noreferrer">WaitIterateAll</a>等待IterateAll异步接口返回。</p><p>IterateAll异步模式的关键代码示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::Matmul&lt;aType, bType, cType, biasType&gt; mm;</span></span>
<span class="line"><span>mm.SetTensorA(queryGm[tensorACoreOffset]);</span></span>
<span class="line"><span>mm.SetTensorB(keyGm[tensorBCoreOffset + sInnerStart * singleProcessSInnerSize *</span></span>
<span class="line"><span>      tilingData-&gt;attentionScoreOffsetStrideParams.matmulHead], true);</span></span>
<span class="line"><span>mm.SetTail(singleProcessSOuterSize, mmNNum);</span></span>
<span class="line"><span>mm.template IterateAll&lt;false&gt;(workspaceGm[tmp_block_idx * mmResUbSize * sInnerLoopTimes],0, false,true);</span></span>
<span class="line"><span>// 执行其他操作</span></span>
<span class="line"><span>mm.WaitIterateAll(); // 等待IterateAll完成</span></span>
<span class="line"><span>DataCopy(dstUB, GM);  // 进行GM到UB的拷贝</span></span></code></pre></div></li></ul></li></ul><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><ul><li>Iterate&amp;GetTensorC的同步：MIX场景（包含矩阵计算和矢量计算）、纯Cube场景（只有矩阵计算）。</li><li>Iterate&amp;GetTensorC的异步：仅MIX场景（包含矩阵计算和矢量计算）。</li><li>IterateAll的同步：MIX场景（包含矩阵计算和矢量计算）、纯Cube场景（只有矩阵计算）。</li><li>IterateAll的异步：仅MIX场景（包含矩阵计算和矢量计算）。</li></ul><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>Iterate&amp;GetTensorC的异步场景：</p><ul><li>传入的C矩阵地址空间大小需要保证不小于baseM * baseN。</li><li>SetWorkspace接口需要在Iterate接口之前调用。</li><li>支持只输出到VECIN、只输出到Global Memory，同时输出到Global Memory和VECIN三种输出方式。</li><li>取出C矩阵到VECIN时，数据格式仅支持NZ；取出C矩阵到GM时，数据格式支持ND或NZ。</li></ul></li><li><p>IterateAll的异步场景：</p><ul><li>传入的C矩阵地址空间大小需要保证不小于singleCoreM * singleCoreN。</li><li>仅支持连续输出至Global Memory。</li></ul></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li>Iterate&amp;GetTensorC的异步场景的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_fused" target="_blank" rel="noreferrer">异步场景样例</a>、<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_async_iterate" target="_blank" rel="noreferrer">Iterate异步场景样例</a>。</li><li>IterateAll的异步场景的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_async_iterate_all" target="_blank" rel="noreferrer">IterateAll异步场景样例</a>。</li></ul>`,11)])])}const g=a(p,[["render",r]]);export{h as __pageData,g as default};
